  "action.castIdentityNote": "पहचान स्टिल ({{count}}): हर पैनल में चेहरा/शरीर संलग्न कास्ट से मेल खाए।",
  "tpl.system.polishOnly": "रेसिपी केवल पॉलिश: पहचान और संसार बनाए रखें। शब्द निखारें। युग, मौसम, पेशा, स्थान या नमूना संसार न गढ़ें। बोली भाषा न गढ़ें। डिफ़ॉल्ट कठोर नियम प्रोफ़ाइल में न लिखें।",
  "tpl.system.fillBlanks": "रेसिपी केवल खाली: केवल खाली कुंजियाँ भरें। भरी फ़ील्ड न बदलें। नया संसार न गढ़ें।",
  "tpl.system.invent": "रेसिपी आविष्कार: उपयोगकर्ता ने स्वतंत्र रचना दी। हर फ़िल्माई कुंजी पूरी करें। Demo या इस अनुरोध से बाहर संसार न लाएँ।",
  "tpl.system.fromStory": "रेसिपी कहानी से: केवल इसी अनुरोध का शीर्षक/शैली/कास्ट/दृश्य continuity के लिए। टकराव में उपयोगकर्ता idea जीते।",
  "tpl.system.followAsset": "रेसिपी संपत्ति के अनुसार: दी गई शैली अपनाएँ। सामग्री न कहे तो सिनेमाई लुक, खाली सेट, 6–10 सेकंड न थोपें। अवधि क्लिप की असली सेकंड।",
  "tpl.system.cinematicLock": "रेसिपी सिनेमा+भ्रम-रोध: सिनेमाई लुक; खाली सेट; वॉटरमार्क/लोगो/अतिरिक्त चेहरे नहीं; दो हाथ/बाँह/टाँग जब तक गैर-मानव न हो।",
  "tpl.system.identityLock": "रेसिपी पहचान ताला: चेहरा/शरीर/पोशाक/स्थान/प्रॉप स्टिल पर ताला। दूसरा व्यक्ति/स्थान/वस्तु न बदलें।",
  "tpl.system.restyle": "रेसिपी restyle: वही व्यक्ति। पोशाक, सेट, युग उपयोगकर्ता कहे तो बदल सकते हैं। दूसरा व्यक्ति नहीं।",
  "pipeline.character.system": "आप पात्र बाइबल निखारते हैं। प्रत्येक 3–5 पंक्तियाँ: रूप, आवाज़, प्रेरणा, इशारा। केवल इस अनुरोध के तथ्य।",
  "pipeline.scene.system": "दृश्यों को दृश्य बीट शीट में फैलाएँ। वास्तविक अवधि; 6–10 सेकंड न मानें। केवल दिए दृश्य।",
  "pipeline.props.system": "प्रॉप निरंतरता निखारें। रंग, आकार, कब आए। सूची से बाहर प्रॉप न गढ़ें।",
  "pipeline.script.system": "आप पटकथा लेखक हैं। प्रत्येक दृश्य के लिए संक्षिप्त स्क्रीनप्ले। वास्तविक अवधि; 10 सेकंड न थोपें। प्रारूप:\n### SCENE <number> | id=<id>\n<script body>",
  "pipeline.script.noScenes": "(कोई दृश्य नहीं — स्थान न गढ़ें)",
  "keyArt.task": "कथा “{{title}}” का की-आर्ट {{n}}। एक पूर्ण प्रचार चित्र। कॉमिक पैनल, पैनल संख्या या ऐप UI नहीं।",
  "keyArt.lockCover": "कवर पोस्टर: कहानी कार्ड के लिए आड़ा की-आर्ट। शीर्षक के लिए शांत पट्टी छोड़ें। चेहरे पढ़े जाएँ। लोगो या नकली क्रेडिट न बनाएँ।",
  "keyArt.lockPoster": "खड़ा पोस्टर: एक अकेला वन-शीट। फ़ोन पर भी नायक दिखे। फ्रेम में और पोस्टर न हों।",
  "keyArt.lockStill": "स्टिल: ड्रामा से निकाला गया सिनेमाई फ़्रेम। स्वाभाविक अभिनय, वास्तविक स्थान। कोलाज नहीं।",
  "keyArt.lockPromo": "प्रोमो: पात्र और संसार एक फ्रेम में। मज़बूत सिल्हूट, एक मूड। कॉन्टैक्ट शीट नहीं।",
  "keyArt.lockSocial": "सोशल स्टोरी: 9:16 खड़ा टीज़र। विषय बड़ा। टेक्स्ट के लिए हाशिया।",
  "keyArt.lockHeadshot": "नायक क्लोज़-अप: सामने का चेहरा पूरा फ्रेम, संदर्भों से वही पहचान। कंधे चल सकते हैं। और कोई व्यक्ति नहीं।",
  "keyArt.lockBust": "बस्ट प्रोमो: छाती से ऊपर, वेशभूषा का कॉलर दिखे, कैमरे की ओर देखें।",
  "keyArt.lockGroup": "समूह: सभी नामित पात्र एक फ्रेम में, वही संसार और प्रकाश। चेहरा न छोड़ें न बदलें।",
  "keyArt.formatLockTall": "फ़ॉर्मेट लॉक: पूरी छवि ऊँची 9:16 है। आड़ा वाइडस्क्रीन नहीं।",
  "keyArt.formatLockSquare": "फ़ॉर्मेट लॉक: पूरी छवि वर्ग 1:1 है।",
  "keyArt.formatLockWide": "फ़ॉर्मेट लॉक: पूरी छवि चौड़ी 16:9 है।",
  "keyArt.methodFreshLock": "विधि: नई छवि बनाएँ। संदर्भ केवल पहचान के लिए। पुरानी टेक की पिक्सेल रचना न नकल करें।",
  "keyArt.methodEditLock": "विधि: संलग्न अपनी छवि संपादित करें। संक्षिप्त निर्देश न कहे तो रचना रखें।",
  "keyArt.methodIdentityLock": "विधि: चेहरे पात्र-संदर्भों से बँधे। मुद्रा, क्रॉप और वेश बदल सकते हैं।",
