  "plate.scene.layout.identity_lock": "चौड़ा 16:9 ठीक दो बराबर पैनल उसी स्थान के: (1) सामने मुख्य कोण (2) ~45° तीन-चौथाई। वही सामग्री, साइन, पैलेट।",
  "plate.scene.layout.low_angle": "ऊँचा 9:16 निम्न-कोण वास्तुकला / छत / छतरी ऊपर देखता, नाटक पैमाने के लिए। चेहरे नहीं।",
  "plate.scene.layout.high_angle": "चौड़ा 16:9 उच्च-कोण फ़र्श योजना / सड़क ज्यामिति ब्लॉकिंग संदर्भ के लिए। चेहरों से खाली।",
  "plate.scene.layout.pov_enter": "चौड़ा 16:9 प्रथम-पुरुष प्रवेश POV दरवाज़े या गली मुँह से स्थान में। दहलीज के पार खाली सेट।",
  "plate.scene.layout.over_shoulder_empty": "चौड़ा 16:9 कंधे-पार खाली फ्रेम: केवल नरम अनाम कंधा सिल्हूट, स्थान की तीखी पृष्ठभूमि संवाद ब्लॉकिंग के लिए।",
  "plate.scene.layout.day_clear": "चौड़ा 16:9 वही स्थान साफ़ दिन के प्रकाश में, प्राकृतिक सूर्य दिशा, पठनीय छायाएँ, सूखी सतहें।",
  "plate.scene.layout.golden_hour": "चौड़ा 16:9 वही स्थान स्वर्ण घंटे पर: गर्म लंबी छायाएँ, अंबर रिम प्रकाश, रोमांटिक लघु-नाटक मूड, चेहरों से खाली।",
  "plate.scene.layout.night_neon": "चौड़ा 16:9 वही स्थान रात में प्रैक्टिकल / नियॉन / सड़क लैंप के साथ, वैकल्पिक सियान-मैजेंटा फैलाव, वैकल्पिक गीलापन, चेहरों से खाली।",
  "plate.scene.layout.rain_wet": "चौड़ा 16:9 वही स्थान बारिश में: गीला डामर/प्रतिबिंब, वर्षा रेखाएँ, ठंडा ग्रेड, छाते केवल दूर के प्रॉप, चेहरे नहीं।",
  "plate.scene.layout.fog_mood": "चौड़ा 16:9 वही स्थान कोहरे/धुएँ में: नरम गहराई परतें, मंद पैलेट, रहस्य मूड, वास्तुकला फिर भी पठनीय, चेहरे नहीं।",
  "plate.scene.layout.set_dressing": "वर्ग 1:1 मेज़ / काउंटर / शेल्फ सेट-ड्रेसिंग बोर्ड इस स्थान के मुख्य प्रॉप का, लोग नहीं।",
  "plate.scene.layout.material_board": "वर्ग 1:1 सामग्री निरंतरता बोर्ड: इस स्थान की दीवार, फ़र्श, धातु/लकड़ी, कपड़ा। निकट विवरण, चेहरे नहीं, पूर्ण-शरीर पात्र नहीं।",
  "plate.scene.layout.signage_prop": "वर्ग 1:1 पठनीय साइन / स्थलचिह्न प्रॉप क्लोज़-अप स्थान पहचान लॉक के लिए। तीखे पाठ-जैसे आकार (ज़रूरत हो तो गढ़े ग्लिफ़)। चेहरे नहीं।",
  "plate.scene.layout.lighting_ref": "चौड़ा 16:9 खाली सेट का प्रकाश संदर्भ: स्पष्ट मुख्य प्रकाश दिशा, फ़िल, प्रैक्टिकल, पात्र नहीं।",
